-- ============================================================
-- SoftStock — DELIVERIES UNIT FIX
-- The earlier migration converted delivery weights from kg to metres
-- using an unverified formula; for light/narrow specs this produced
-- absurd numbers (millions of metres). This script replaces all
-- migrated deliveries with their HONEST original kg weight instead —
-- no guessed conversion. The app now shows this column in kg.
-- Replaces 103 delivery rows. Safe to run only if you have not
-- manually added real deliveries in the app yet (this clears the table).
-- ============================================================

alter table products  add column if not exists import_key text;
alter table suppliers add column if not exists import_key text;
alter table deliveries add column if not exists unit text default 'm';

-- tag products/suppliers for matching
update products set import_key = 'ռուլոն սպիտակ|facial tissue|20.0|3.0|14.0' where name = 'Ռուլոն սպիտակ' and type = 'Facial Tissue' and coalesce(width_cm,-1) = coalesce(20.0,-1) and ply = 3 and coalesce(gsm,-1) = coalesce(14.0,-1) and import_key is null;
